'use strict';
// NEW v11: treaties, finite cargo caravans, kingdom milestones and live diplomacy.
// Reuses terrain routing, the existing sprite atlases, clock and RAF loop.
const kingdomLifeOld={simulate,newWorld,restore,snapshot,setDiplomacy,hostilityChance,paintDepthWorld,worldDepthItems,smoothDraw};
const convoyCapacity=24;
let kingdomLife=freshKingdomLife(),civicTimer=0,civicUiTimer=0,convoySerial=0;
const convoyPool=Array.from({length:convoyCapacity},()=>({active:false}));
function freshKingdomLife(){return{treaties:{},milestones:{},settings:{autoDiplomacy:true,showRoutes:true},delivered:0,lost:0};}
function activeKingdomIds(){const ids=new Set();for(const e of entities)if(e.kind==='human'&&e.hp>0){const v=villages.find(v=>v.id===e.village);if(v)ids.add(v.kingdom);}return ids;}
function kingdomName(id){return kingdoms.find(k=>k.id===id)?.name||'Vương quốc đã mất';}
function treatyFor(a,b,create=true){const key=pairKey(a,b),existing=kingdomLife.treaties[key];if(existing)return existing;const t={score:kingdomRace(a)===kingdomRace(b)?10:-15,allied:false,trade:true,deliveries:0,lastChanged:simTime};if(create)kingdomLife.treaties[key]=t;return t;}
function treatyStatus(a,b){if(atWar(a,b))return'Chiến tranh';const t=treatyFor(a,b,false);return t.allied?'Liên minh':relations[pairKey(a,b)]?.truceUntil>simTime?'Đình chiến':t.score>=25?'Thân thiện':t.score<=-35?'Căng thẳng':'Trung lập';}
function setTreaty(a,b,action){a=Number(a);b=Number(b);const active=activeKingdomIds();if(a===b||!active.has(a)||!active.has(b))throw Error('Chọn hai vương quốc còn cư dân.');const t=treatyFor(a,b);
 if(action==='ally'){if(atWar(a,b))throw Error('Hãy lập hòa ước trước khi liên minh.');t.allied=true;t.trade=true;t.score=Math.max(45,t.score);remember(kingdomName(a)+' liên minh với '+kingdomName(b)+'.','civil');}
 else if(action==='break'){t.allied=false;t.score=Math.max(-100,t.score-25);relations[pairKey(a,b)]={truceUntil:simTime+120};remember(kingdomName(a)+' và '+kingdomName(b)+' chấm dứt liên minh.','civil');}
 else if(action==='trade'){if(atWar(a,b))throw Error('Không thể mở giao thương khi đang chiến tranh.');t.trade=true;remember(kingdomName(a)+' và '+kingdomName(b)+' mở giao thương.','civil');}
 else if(action==='embargo'){t.trade=false;t.score=Math.max(-100,t.score-10);for(const c of convoyPool)if(c.active&&pairKey(c.a,c.b)===pairKey(a,b))cancelConvoy(c,'bị đình chỉ');remember(kingdomName(a)+' và '+kingdomName(b)+' đóng giao thương.','civil');}
 else throw Error('Lệnh ngoại giao không hợp lệ.');t.lastChanged=simTime;renderKingdomLife();}
// MODIFIED: an explicit war command breaks an alliance; automatic war respects it.
setDiplomacy=function(a,b,state){kingdomLifeOld.setDiplomacy(a,b,state);a=Number(a);b=Number(b);const t=treatyFor(a,b);t.allied=false;t.score=state==='war'?-70:Math.max(0,t.score);t.lastChanged=simTime;if(state==='war')for(const c of convoyPool)if(c.active&&pairKey(c.a,c.b)===pairKey(a,b))cancelConvoy(c,'dừng vì chiến tranh');renderKingdomLife();};
hostilityChance=function(a,b){const t=treatyFor(a,b);if(t.allied)return 0;return Math.max(.01,Math.min(.95,kingdomLifeOld.hostilityChance(a,b)*(1-t.score/140)));};
function materialLimit(v,type){return type==='food'?10000:type==='wood'?500:resourceCap(v);}
function refundConvoy(c){const v=villages.find(v=>v.id===c.from);if(!v)return 0;const amount=Math.min(c.amount,Math.max(0,materialLimit(v,c.type)-readMaterial(v,c.type)));changeMaterial(v,c.type,amount);return amount;}
function cancelConvoy(c,reason,refund=true){if(!c.active)return;const restored=refund?refundConvoy(c):0;kingdomLife.lost+=c.amount-restored;c.active=false;if(reason)remember('Đoàn hàng '+c.label+' '+reason+'.','civil');}
function startConvoy(from,to,type,amount){ensureVillageEconomy(from);ensureVillageEconomy(to);if(!['food','wood',...oreKinds].includes(type)||from.id===to.id||!Number.isFinite(amount)||amount<=0)return false;if(atWar(from.kingdom,to.kingdom)||from.kingdom!==to.kingdom&&!treatyFor(from.kingdom,to.kingdom).trade)return false;if(!hasBuilding(from,'market')||!hasBuilding(to,'market')||!humans().some(e=>e.village===from.id&&e.job==='merchant'&&isOnDuty(e)))return false;
 const c=convoyPool.find(c=>!c.active);if(!c||convoyPool.some(c=>c.active&&c.from===from.id&&c.to===to.id))return false;amount=Math.min(amount,readMaterial(from,type),Math.max(0,materialLimit(to,type)-readMaterial(to,type)));if(amount<=0)return false;
 const sailing=from.tech>=2&&to.tech>=2,probe={x:from.x,y:from.y,sailing};if(!pathStep(probe,to,sailing))return false;
 amount=Math.min(100,amount);changeMaterial(from,type,-amount);Object.assign(c,{active:true,id:++convoySerial,from:from.id,to:to.id,a:from.kingdom,b:to.kingdom,type,amount,x:from.x,y:from.y,previousX:from.x,previousY:from.y,tx:from.x,ty:from.y,sailing,age:0,replan:0,label:from.name+' → '+to.name});return true;}
// MODIFIED: replace instant stock teleportation with capped, visible shipments.
tradeResources=function(){const people=humans(),merchantVillages=new Set(people.filter(e=>e.job==='merchant'&&isOnDuty(e)).map(e=>e.village));const candidates=villages.filter(v=>hasBuilding(v,'market')&&people.some(e=>e.village===v.id));let sent=0;
 for(let i=0;i<candidates.length&&sent<4;i++)for(let j=i+1;j<candidates.length&&sent<4;j++){const a=candidates[i],b=candidates[j];if(Math.hypot(a.x-b.x,a.y-b.y)>60||atWar(a.kingdom,b.kingdom)||a.kingdom!==b.kingdom&&!treatyFor(a.kingdom,b.kingdom).trade)continue;for(const type of ['food','wood',...oreKinds]){const delta=readMaterial(a,type)-readMaterial(b,type),minimum=type==='food'?45:type==='wood'?25:12;if(Math.abs(delta)<minimum)continue;const from=delta>0?a:b,to=delta>0?b:a;if(!merchantVillages.has(from.id))continue;const reserve=type==='food'?Math.max(35,people.filter(e=>e.village===from.id).length*5):type==='wood'?20:6,amount=Math.min(type==='food'?12:6,Math.abs(delta)/4,readMaterial(from,type)-reserve);if(amount>0&&startConvoy(from,to,type,amount)){sent++;break;}}}}
function moveConvoys(dt){for(const c of convoyPool){if(!c.active)continue;c.previousX=c.x;c.previousY=c.y;c.age+=dt;c.replan-=dt;const from=villages.find(v=>v.id===c.from),to=villages.find(v=>v.id===c.to);if(!from||!to||!humans().some(e=>e.village===to.id)){cancelConvoy(c,'không còn điểm nhận');continue;}if(from.kingdom!==c.a||to.kingdom!==c.b||atWar(c.a,c.b)||c.a!==c.b&&!treatyFor(c.a,c.b).trade){cancelConvoy(c,'dừng do thay đổi ngoại giao');continue;}if(grid[idx(c.x,c.y)]?.fire){cancelConvoy(c,'mất trong hỏa hoạn',false);continue;}if(c.age>240){cancelConvoy(c,'quay về vì đường bị chặn');continue;}
 if(Math.hypot(c.x-to.x,c.y-to.y)<1.2){const received=Math.min(c.amount,Math.max(0,materialLimit(to,c.type)-readMaterial(to,c.type)));changeMaterial(to,c.type,received);c.amount-=received;if(c.amount>0)kingdomLife.lost+=c.amount-refundConvoy(c);c.active=false;kingdomLife.delivered+=received;if(c.a!==c.b&&received>0){const t=treatyFor(c.a,c.b);t.score=Math.min(100,t.score+3);t.deliveries++;if(t.deliveries===1||t.deliveries%10===0)remember(c.label+' giao thành công '+Math.floor(received)+' '+(c.type==='food'?'lương thực':c.type==='wood'?'gỗ':resourceNames[c.type].toLowerCase())+'.','civil');}continue;}
 if(c.replan<=0||Math.hypot(c.tx-c.x,c.ty-c.y)<.05){const next=pathStep(c,to,c.sailing);if(next){c.tx=next.x;c.ty=next.y;}c.replan=.7;}const dx=c.tx-c.x,dy=c.ty-c.y,len=Math.hypot(dx,dy);if(len>.001){const step=Math.min(len,dt*1.7),x=c.x+dx/len*step,y=c.y+dy/len*step;if(inside(x,y)&&grid[idx(x,y)].t!==4&&(c.sailing||grid[idx(x,y)].t!==0)&&clearRoute(c,{x,y})){c.x=x;c.y=y;}else c.replan=0;}
 }}
function civicPulse(){const active=activeKingdomIds(),live=kingdoms.filter(k=>active.has(k.id));for(const k of live){const lands=villages.filter(v=>v.kingdom===k.id),people=members(k.id),m=kingdomLife.milestones[k.id]??={population:0,tech:0,shortage:false};const peak=Math.max(0,...lands.map(v=>v.tech));for(const level of [25,50,100,200])if(people.length>=level&&m.population<level){m.population=level;remember(k.name+' đạt '+level+' cư dân.','civil');}if(peak>m.tech){m.tech=peak;remember(k.name+' bước vào thời kỳ '+techNames[peak]+'.','civil');}const shortage=lands.some(v=>v.food<Math.max(5,people.filter(e=>e.village===v.id).length*2));if(shortage&&!m.shortage)remember(k.name+' đang thiếu lương thực. Hãy giúp ruộng và nguồn thức ăn.','civil');m.shortage=shortage;}
 if(!kingdomLife.settings.autoDiplomacy)return;for(let i=0;i<live.length;i++)for(let j=i+1;j<live.length;j++){const a=live[i],b=live[j],t=treatyFor(a.id,b.id);if(atWar(a.id,b.id)||t.allied||simTime-t.lastChanged<120)continue;if(t.score>=45&&t.deliveries>=4&&random()<.15){t.allied=true;t.lastChanged=simTime;remember(a.name+' và '+b.name+' tự ký liên minh sau nhiều chuyến giao thương.','civil');}}}
// NEW: use existing draw depth; carriers can be hidden behind trees and buildings.
worldDepthItems=function(...args){const items=kingdomLifeOld.worldDepthItems(...args),[minX,maxX,minY,maxY]=args;for(const c of convoyPool)if(c.active&&c.x>=minX&&c.x<maxX&&c.y>=minY&&c.y<maxY)items.push({type:'convoy',c,depth:spriteGround(c.y,1.35)});return items.sort((a,b)=>a.depth-b.depth);};
function paintConvoy(c){drawSprite(4,c.x,c.y,1.35);const icon=c.type==='food'?11:c.type==='wood'?0:null;if(icon!==null)drawSprite(icon,c.x+.35,c.y-.5,.45);else drawEconomySprite(oreSprites[c.type],c.x+.35,c.y-.5,.55);}
paintDepthWorld=function(...args){if(kingdomLife.settings.showRoutes){ctx.save();ctx.setLineDash([.4,.6]);ctx.lineWidth=.07;ctx.strokeStyle='#f6d48770';for(const c of convoyPool)if(c.active){ctx.beginPath();ctx.moveTo(c.x,c.y);ctx.lineTo(c.tx,c.ty);ctx.stroke();}ctx.restore();}kingdomLifeOld.paintDepthWorld(...args);};
// NEW: interpolate carriers without per-frame entity allocations.
const convoyRealX=new Float64Array(convoyCapacity),convoyRealY=new Float64Array(convoyCapacity);
smoothDraw=function(alpha){for(let i=0;i<convoyCapacity;i++){const c=convoyPool[i];if(!c.active)continue;convoyRealX[i]=c.x;convoyRealY[i]=c.y;c.x=c.previousX+(c.x-c.previousX)*alpha;c.y=c.previousY+(c.y-c.previousY)*alpha;}try{kingdomLifeOld.smoothDraw(alpha);}finally{for(let i=0;i<convoyCapacity;i++){const c=convoyPool[i];if(c.active){c.x=convoyRealX[i];c.y=convoyRealY[i];}}}};
simulate=function(dt){kingdomLifeOld.simulate(dt);moveConvoys(dt);civicTimer+=dt;civicUiTimer+=dt;if(civicTimer>=10){civicTimer%=10;civicPulse();}if(civicUiTimer>=2){civicUiTimer%=2;if($('kingdom-life-dialog').open)renderKingdomLife();}};
function resetKingdomLife(){kingdomLife=freshKingdomLife();for(const c of convoyPool)c.active=false;civicTimer=civicUiTimer=convoySerial=0;}
newWorld=function(...args){kingdomLifeOld.newWorld(...args);resetKingdomLife();};
snapshot=function(){return{...kingdomLifeOld.snapshot(),version:10,kingdomLife:JSON.parse(JSON.stringify(kingdomLife)),convoys:convoyPool.filter(c=>c.active).map(c=>({...c}))};};
function validateKingdomLife(d){const n=(x,a,b)=>Number.isFinite(x)&&x>=a&&x<=b,ids=new Set(d.kingdoms?.map(k=>k.id)),vIds=new Set(d.villages?.map(v=>v.id)),validPair=key=>{if(!/^\d+:\d+$/.test(key))return false;const [a,b]=key.split(':').map(Number);return a<b&&ids.has(a)&&ids.has(b);},s=d.kingdomLife;
 if(!s||!s.settings||typeof s.settings.autoDiplomacy!=='boolean'||typeof s.settings.showRoutes!=='boolean'||!n(s.delivered,0,1e12)||!n(s.lost,0,1e12)||!s.treaties||Array.isArray(s.treaties)||Object.keys(s.treaties).length>4950||!Object.entries(s.treaties).every(([key,t])=>validPair(key)&&t&&n(t.score,-100,100)&&typeof t.allied==='boolean'&&typeof t.trade==='boolean'&&Number.isInteger(t.deliveries)&&n(t.deliveries,0,1e9)&&n(t.lastChanged,0,1e10))||!s.milestones||Array.isArray(s.milestones)||Object.keys(s.milestones).length>100||!Object.entries(s.milestones).every(([key,m])=>ids.has(Number(key))&&m&&n(m.population,0,100000)&&n(m.tech,0,4)&&typeof m.shortage==='boolean'))throw Error('Dữ liệu ngoại giao không hợp lệ.');
 if(!Array.isArray(d.convoys)||d.convoys.length>convoyCapacity||new Set(d.convoys.map(c=>c.id)).size!==d.convoys.length||!d.convoys.every(c=>c.active===true&&Number.isInteger(c.id)&&n(c.id,1,1e10)&&vIds.has(c.from)&&vIds.has(c.to)&&c.from!==c.to&&ids.has(c.a)&&ids.has(c.b)&&['food','wood',...oreKinds].includes(c.type)&&n(c.amount,.0001,100)&&n(c.x,0,W-.0001)&&n(c.y,0,H-.0001)&&n(c.previousX,0,W-.0001)&&n(c.previousY,0,H-.0001)&&n(c.tx,0,W-.0001)&&n(c.ty,0,H-.0001)&&typeof c.sailing==='boolean'&&n(c.age,0,240)&&n(c.replan,-1,1)&&typeof c.label==='string'&&c.label.length<=250))throw Error('Dữ liệu đoàn hàng không hợp lệ.');}
restore=function(input){const d=JSON.parse(JSON.stringify(input)),modern=d?.version===10;if(modern){validateKingdomLife(d);d.version=9;}kingdomLifeOld.restore(d);resetKingdomLife();if(modern){kingdomLife=d.kingdomLife;for(let i=0;i<d.convoys.length;i++){Object.assign(convoyPool[i],d.convoys[i]);convoySerial=Math.max(convoySerial,d.convoys[i].id);}}renderKingdomLife();};
function buildKingdomLifeUI(){const button=document.createElement('button');button.id='kingdom-life-open';button.textContent='⚑ Đời sống';document.querySelector('.civil-bar').append(button);const dialog=document.createElement('dialog');dialog.id='kingdom-life-dialog';dialog.className='wide-dialog';dialog.innerHTML='<button class="close" aria-label="Đóng">×</button><span class="dialog-kicker">CÁC NỀN VĂN MINH ĐANG SỐNG</span><h2>Liên minh & giao thương</h2><div class="civic-settings"><label><input id="auto-alliance" type="checkbox"> Tự hình thành liên minh qua giao thương</label><label><input id="show-convoys" type="checkbox"> Hiện chặng đi của đoàn hàng</label></div><div id="civic-summary"></div><div class="diplomacy"><label>Nước thứ nhất<select id="civic-a"></select></label><label>Nước thứ hai<select id="civic-b"></select></label></div><div class="civic-actions"><button data-treaty="ally">Liên minh</button><button data-treaty="break">Hủy liên minh</button><button data-treaty="trade">Mở giao thương</button><button data-treaty="embargo">Đóng giao thương</button></div><p class="dialog-note">Hai khu định cư cần chợ, thương nhân đang làm việc và đường đi phù hợp để trao đổi hàng. Nước đã liên minh không tự tuyên chiến với nhau. Lệnh tuyên chiến của bạn vẫn có hiệu lực.</p><div id="civic-pairs"></div><h3>Đoàn hàng trên đường</h3><div id="civic-convoys"></div>';document.body.append(dialog);dialog.querySelector('.close').onclick=()=>dialog.close();button.onclick=()=>{renderKingdomLife();dialog.showModal();};for(const b of dialog.querySelectorAll('[data-treaty]'))b.onclick=()=>{try{setTreaty($('civic-a').value,$('civic-b').value,b.dataset.treaty);}catch(e){toast(e.message);}};$('auto-alliance').onchange=e=>kingdomLife.settings.autoDiplomacy=e.target.checked;$('show-convoys').onchange=e=>kingdomLife.settings.showRoutes=e.target.checked;}
function renderKingdomLife(){if(!$('civic-pairs'))return;const active=activeKingdomIds(),live=kingdoms.filter(k=>active.has(k.id));for(const id of ['civic-a','civic-b']){const select=$(id),before=select.value;select.replaceChildren();for(const k of live){const o=document.createElement('option');o.value=k.id;o.textContent=k.name;select.append(o);}if(live.some(k=>String(k.id)===before))select.value=before;}if($('civic-a').value===$('civic-b').value&&live.length>1)$('civic-b').selectedIndex=1;$('auto-alliance').checked=kingdomLife.settings.autoDiplomacy;$('show-convoys').checked=kingdomLife.settings.showRoutes;
 for(const b of $('kingdom-life-dialog').querySelectorAll('[data-treaty]'))b.disabled=live.length<2;
 $('civic-summary').textContent=live.length+' vương quốc · '+convoyPool.filter(c=>c.active).length+' đoàn hàng · '+Math.floor(kingdomLife.delivered)+' hàng đã giao';const box=$('civic-pairs');box.replaceChildren();let rows=0;for(let i=0;i<live.length&&rows<40;i++)for(let j=i+1;j<live.length&&rows<40;j++){const a=live[i],b=live[j],t=treatyFor(a.id,b.id,false),row=document.createElement('article'),title=document.createElement('b'),p=document.createElement('p');title.textContent=a.name+' ↔ '+b.name;p.textContent=treatyStatus(a.id,b.id)+' · Quan hệ '+Math.round(t.score)+' · '+(t.trade&&!atWar(a.id,b.id)?'Giao thương mở':'Giao thương đóng')+' · '+t.deliveries+' chuyến thành công';row.append(title,p);box.append(row);rows++;}if(!rows)box.textContent='Cần hai vương quốc có cư dân để thiết lập ngoại giao.';const deliveries=$('civic-convoys');deliveries.replaceChildren();for(const c of convoyPool)if(c.active){const p=document.createElement('p');p.textContent=c.label+' · '+c.amount.toFixed(1)+' '+(c.type==='food'?'lương thực':c.type==='wood'?'gỗ':resourceNames[c.type])+(c.sailing?' · Có thể vượt biển':' · Đường bộ');deliveries.append(p);}if(!deliveries.children.length)deliveries.textContent='Chưa có đoàn hàng. Hãy xây chợ ở hai khu định cư, bổ nhiệm thương nhân và giữ đường đi an toàn.';}
buildKingdomLifeUI();
window.mamWorld={...window.mamWorld,snapshot:()=>snapshot(),restore:d=>restore(d),newWorld:(...a)=>newWorld(...a),simulate:dt=>simulate(dt),setDiplomacy:(...a)=>setDiplomacy(...a),setTreaty,getKingdomLife:()=>({settings:{...kingdomLife.settings},delivered:kingdomLife.delivered,lost:kingdomLife.lost,treaties:JSON.parse(JSON.stringify(kingdomLife.treaties)),convoys:convoyPool.filter(c=>c.active).map(c=>({...c}))})};
